ids = [c[0] for c in C]
assert len(ids) == len(set(ids)), "duplicate ids"
for i in ids:
    m = re.fullmatch(r"C(\d{3})", i); assert m, i
    n = int(m.group(1)); assert 86 <= n <= 135, f"out of range {i}"
assert ids == sorted(ids), "ids not in order"
known = set(ids)
kinds = {"OBSERVATION","SOURCE_REPORT","FORMAL_DERIVATION","INFERENCE","HYPOTHESIS","PREDICTION","DEFINITION","NORMATIVE","PROPOSAL"}
times = {"pi-0fb90672","mw-69cb016d","history","none"}
import os
rows = []
for (cid, loc, kind, text, quote, scope, tc, material, cited, deps) in C:
    assert kind in kinds, (cid, kind)
    assert tc in times, (cid, tc)
    assert quote in doc, f"{cid}: strongestWording not verbatim in doc: {quote!r}"
    for d in deps: assert d in known, (cid, d)
    for p in cited: assert os.path.exists(f"{ROOT}/{p}"), (cid, p)
    rows.append({"id":cid,"doc":DOC,"loc":loc,"kind":kind,"text":text,"strongestWording":quote,
                 "scope":scope,"timeContext":tc,"material":bool(material),"citedPaths":cited,"deps":deps})
with open(OUT,"w",encoding="utf-8") as f:
    for r in rows: f.write(json.dumps(r, ensure_ascii=False)+"\n")
print("wrote", OUT, len(rows))
from collections import Counter
print(Counter(r["kind"] for r in rows))
print("material:", sum(r["material"] for r in rows))
print("obs/inf ids:", [r["id"] for r in rows if r["kind"] in ("OBSERVATION","INFERENCE")])
